import { useLiveQuery } from 'dexie-react-hooks';
import { useState } from 'react';
import { db } from '../services/db';
import { returnSale } from '../services/returns';
import type { User } from '../types/models';

export default function Returns({ user }: { user: User }) {
  const sales = useLiveQuery(
    () => db.sales.orderBy('created_at').reverse().toArray(),
    [],
  ) || [];
  const returns = useLiveQuery(async () => {
    const rows = await db.returns.toArray();
    return rows.sort((a, b) =>
      String(b.created_at).localeCompare(String(a.created_at)),
    );
  }, []) || [];
  const [saleId, setSaleId] = useState('');
  const [reason, setReason] = useState('');
  const [message, setMessage] = useState('');

  async function save(e: React.FormEvent) {
    e.preventDefault();
    setMessage('');
    if (!saleId) return setMessage('اختر فاتورة مكتملة.');
    if (!reason.trim()) return setMessage('اكتب سبب المرتجع.');
    try {
      await returnSale(user.id, saleId, reason);
      setSaleId('');
      setReason('');
      setMessage('تم ترجيع الفاتورة وإعادة الكميات للمخزون.');
    } catch (error: any) {
      setMessage(error?.message || 'تعذر تنفيذ المرتجع.');
    }
  }

  const completedSales = sales.filter((sale) => sale.status === 'COMPLETED');

  return (
    <section>
      <h1>المرتجعات</h1>
      <form className="card formgrid" onSubmit={save}>
        <select value={saleId} onChange={(e) => setSaleId(e.target.value)} required>
          <option value="">اختر فاتورة مكتملة</option>
          {completedSales.map((sale) => (
            <option key={sale.id} value={sale.id}>
              {sale.invoice_no} — {sale.total.toFixed(2)}
            </option>
          ))}
        </select>
        <input
          value={reason}
          onChange={(e) => setReason(e.target.value)}
          placeholder="سبب المرتجع"
          required
        />
        <button className="danger">تنفيذ مرتجع كامل</button>
      </form>
      {message && <div className="alert">{message}</div>}
      <div className="card">
        <table>
          <thead>
            <tr>
              <th>التاريخ</th>
              <th>الفاتورة</th>
              <th>المنتج</th>
              <th>الكمية</th>
              <th>السبب</th>
            </tr>
          </thead>
          <tbody>
            {returns.map((item) => (
              <tr key={item.id}>
                <td>{item.created_at.slice(0, 10)}</td>
                <td>{item.source_id}</td>
                <td>{item.product_id}</td>
                <td>{item.quantity || 0}</td>
                <td>{item.reason || ''}</td>
              </tr>
            ))}
          </tbody>
        </table>
        {!returns.length && <p className="empty">لا توجد مرتجعات بعد.</p>}
      </div>
    </section>
  );
}