import {useLiveQuery} from 'dexie-react-hooks'; import {dashboardStats} from '../services/reports'; import {expiryBuckets,lowStock} from '../services/inventory'; import {money} from '../utils/ids'; import MiniChart from '../components/MiniChart';
export default function Dashboard(){const stats=useLiveQuery(dashboardStats,[]) as any; const low=useLiveQuery(lowStock,[])||[]; const exp=useLiveQuery(expiryBuckets,[]) as any; const cards=[['مبيعات اليوم',stats?.todaySales],['مشتريات اليوم',stats?.todayPurchases],['ربح اليوم',stats?.todayProfit],['المصروفات',stats?.expenses],['قيمة المخزون',stats?.stockValue],['ديون العملاء',stats?.customerDebts],['ديون الموردين',stats?.supplierDebts],['مبيعات آجل',stats?.creditSales]]; return <section><h1>لوحة التحكم</h1><div className="grid cards">{cards.map(([k,v])=><div className="card stat" key={k as string}><span>{k}</span><b>{money(Number(v||0))}</b></div>)}</div><div className="grid two"><div className="card"><h3>تنبيهات المخزون</h3><p>منتجات منخفضة: {low.length}</p><p>منتهية: {exp?.expired?.length||0}</p><p>تنتهي خلال 30 يوم: {(exp?.d7?.length||0)+(exp?.d30?.length||0)}</p></div><div className="card"><h3>مؤشر آخر 30 يوم</h3><MiniChart/></div></div></section>}
