import {useEffect,useState} from 'react'; import {licenseGate} from '../services/license';
export default function OfflineBadge(){const [online,setOnline]=useState(navigator.onLine); useEffect(()=>{const f=()=>setOnline(navigator.onLine); addEventListener('online',f); addEventListener('offline',f); return()=>{removeEventListener('online',f);removeEventListener('offline',f)}},[]); const gate=licenseGate(); return <div className={online?'badge ok':'badge warn'}>{online?'● متصل':'● غير متصل'} <small>{gate.message}</small></div>}
