import { db, getPharmacyId } from './db'; import type {Role,User} from '../types/models'; import { now, uid } from '../utils/ids'; import { audit } from './audit';
const enc=new TextEncoder();
async function digest(value:string,salt:string){ const data=enc.encode(`${salt}:${value}`); const hash=await crypto.subtle.digest('SHA-256',data); return `${salt}:${Array.from(new Uint8Array(hash)).map(b=>b.toString(16).padStart(2,'0')).join('')}`; }
export async function hashPassword(v:string){ return digest(v, crypto.randomUUID()); }
export async function verify(v:string, stored:string){ const [salt, hex]=String(stored||'').split(':'); if(!salt||!hex) return false; return (await digest(v,salt)).endsWith(hex); }
export async function ensureOwner(){ const pharmacy_id=getPharmacyId(); const count=await db.users.count(); if(count===0){ const u:User={id:uid('user'),pharmacy_id,created_at:now(),updated_at:now(),name:'مدير النظام',email:'owner@local',username:'owner',password_hash:await hashPassword('ChangeMe123!'),role:'OWNER',active:true}; await db.users.add(u); await audit(u.id,'user_creation','users',u.id,'Initial local owner created; change password immediately.'); }}
export async function login(username:string,password:string){ const u=await db.users.where('username').equals(username).or('email').equals(username).first(); if(!u||!u.active||!(await verify(password,u.password_hash))) throw new Error('بيانات الدخول غير صحيحة'); localStorage.setItem('alshifaa_session',JSON.stringify({userId:u.id,ts:Date.now()})); await db.users.update(u.id,{last_login:now(),updated_at:now()}); await audit(u.id,'login','users',u.id); return u; }
export async function currentUser(){
 const raw=localStorage.getItem('alshifaa_session');
 if(!raw) return null;
 try {
  const s=JSON.parse(raw);
  if(!s?.userId||!Number.isFinite(Number(s.ts))) return null;
  const settings=await db.settings.get('settings');
  const timeout=Number(settings?.session_timeout_minutes||30)*60*1000;
  if(Date.now()-Number(s.ts)>timeout){ logout(); return null; }
  const user=await db.users.get(s.userId);
  if(!user?.active){ logout(); return null; }
  return user;
 } catch { logout(); return null; }
}
export function logout(){localStorage.removeItem('alshifaa_session')}
export const permissions:Record<Role,string[]>={OWNER:['*'],ADMIN:['*'],PHARMACIST:['pos','products','inventory','customers','reports'],CASHIER:['pos','customers'],INVENTORY:['products','inventory','purchases','suppliers','reports'],ACCOUNTANT:['expenses','payments','reports','customers','suppliers'],VIEWER:['reports']};
export function can(role:Role|undefined,area:string){ return !!role && (permissions[role].includes('*')||permissions[role].includes(area)); }

export async function usersCount(){ return db.users.count(); }
export async function createInitialOwner(input:{pharmacyName:string; ownerName:string; email:string; phone?:string; password:string}){
 if(!input.pharmacyName.trim()||!input.ownerName.trim()||!input.email.trim()) throw new Error('أكمل بيانات الصيدلية والمالك.');
 const existing=await db.users.count(); if(existing>0) throw new Error('تم إعداد حساب المالك مسبقاً');
 const pharmacy_id=getPharmacyId();
 const u:User={id:uid('user'),pharmacy_id,created_at:now(),updated_at:now(),name:input.ownerName,email:input.email,username:input.email,password_hash:await hashPassword(input.password),role:'OWNER',active:true};
 await db.transaction('rw',db.users,db.settings,db.audit_logs,async()=>{
  await db.users.add(u);
  await db.settings.update('settings',{pharmacy_name:input.pharmacyName,email:input.email,phone:input.phone||'',updated_at:now()});
  await audit(u.id,'إنشاء حساب المالك','users',u.id,{pharmacyName:input.pharmacyName,email:input.email});
 });
 localStorage.setItem('alshifaa_session',JSON.stringify({userId:u.id,ts:Date.now()}));
 return u;
}
