import { db, getPharmacyId } from './db'; import { now, uid } from '../utils/ids'; import type {PaymentMethod,Purchase} from '../types/models'; import { audit } from './audit';
export interface PurchaseLine{product_id:string; batch_number:string; quantity:number; purchase_price:number; selling_price:number; expiry_date?:string; manufacture_date?:string; discount:number; tax:number; supplier_id?:string;}
export async function postPurchase(user_id:string, supplier_id:string|undefined, invoice_no:string, paid:number, lines:PurchaseLine[]){ const pharmacy_id=getPharmacyId(); if(!lines.length) throw new Error('أضف صنفاً واحداً على الأقل'); if(!Number.isFinite(paid)||paid<0) throw new Error('المبلغ المدفوع غير صالح'); for(const l of lines){if(!l.product_id||!l.batch_number?.trim()||!Number.isFinite(l.quantity)||l.quantity<=0||!Number.isFinite(l.purchase_price)||l.purchase_price<0||!Number.isFinite(l.selling_price)||l.selling_price<0) throw new Error('بيانات الشراء غير صالحة');} let purchase!:Purchase; await (db.transaction as any)('rw',[db.purchases,db.purchase_items,db.batches,db.stock_movements,db.suppliers,db.audit_logs],async()=>{ let subtotal=0,discount=0,tax=0; for(const l of lines){ subtotal+=l.quantity*l.purchase_price; discount+=l.discount; tax+=(l.quantity*l.purchase_price-l.discount)*(l.tax/100);} const total=subtotal-discount+tax; if(paid>total) throw new Error('المبلغ المدفوع أكبر من إجمالي الشراء'); const normalizedInvoice=String(invoice_no||'').trim()||`P-${Date.now()}`; if(await db.purchases.where('invoice_no').equals(normalizedInvoice).count()) throw new Error('رقم فاتورة الشراء مستخدم مسبقاً'); purchase={id:uid('pur'),pharmacy_id,created_at:now(),updated_at:now(),supplier_id,invoice_no:normalizedInvoice,date:now().slice(0,10),subtotal,discount,tax,total,paid,remaining:Math.max(0,total-paid),status:'POSTED'}; await db.purchases.add(purchase); for(const l of lines){ const batch={id:uid('batch'),pharmacy_id,created_at:now(),updated_at:now(),product_id:l.product_id,batch_number:l.batch_number,quantity:l.quantity,initial_quantity:l.quantity,purchase_price:l.purchase_price,selling_price:l.selling_price,manufacture_date:l.manufacture_date,expiry_date:l.expiry_date,supplier_id}; await db.batches.add(batch); await db.purchase_items.add({id:uid('pitem'),pharmacy_id,created_at:now(),updated_at:now(),purchase_id:purchase.id,product_id:l.product_id,batch_id:batch.id,quantity:l.quantity,purchase_price:l.purchase_price,selling_price:l.selling_price,discount:l.discount,tax:l.tax,line_total:l.quantity*l.purchase_price-l.discount}); await db.stock_movements.add({id:uid('move'),pharmacy_id,created_at:now(),updated_at:now(),product_id:l.product_id,batch_id:batch.id,type:'purchase',quantity:l.quantity,before_qty:0,after_qty:l.quantity,reference_id:purchase.id,user_id}); } if(supplier_id&&purchase.remaining>0){const s=await db.suppliers.get(supplier_id); if(s) await db.suppliers.update(s.id,{balance:s.balance+purchase.remaining,updated_at:now()});} await audit(user_id,'purchase','purchases',purchase.id,purchase); }); return purchase; }
export async function recordPayment(user_id:string, party_type:'customer'|'supplier', party_id:string, amount:number, method:PaymentMethod, notes?:string){ const pharmacy_id=getPharmacyId(); await db.transaction('rw',db.payments,db.customers,db.suppliers,db.audit_logs,async()=>{ const p={id:uid('pay'),pharmacy_id,created_at:now(),updated_at:now(),party_type,party_id,amount,date:now().slice(0,10),method,notes}; await db.payments.add(p); const table=party_type==='customer'?db.customers:db.suppliers; const party=await table.get(party_id) as any; if(party) await table.update(party_id,{balance:Math.max(0,(party.balance||0)-amount),updated_at:now()}); await audit(user_id,'payment','payments',p.id,p); }); }

export async function cancelPurchase(user_id:string,purchase_id:string,reason:string){ const purchase=await db.purchases.get(purchase_id); if(!purchase||purchase.status!=='POSTED') throw new Error('فاتورة الشراء غير قابلة للإلغاء'); await (db.transaction as any)('rw',[db.purchases,db.purchase_items,db.batches,db.stock_movements,db.suppliers,db.audit_logs],async()=>{ const items=await db.purchase_items.where('purchase_id').equals(purchase_id).toArray(); for(const it of items){ const b=await db.batches.get(it.batch_id); if(b){ if(b.quantity<it.quantity) throw new Error('لا يمكن إلغاء الشراء لأن جزءاً من الكمية تم بيعه أو تسويته'); await db.batches.update(b.id,{quantity:b.quantity-it.quantity,updated_at:now()}); await db.stock_movements.add({id:uid('move'),pharmacy_id:purchase.pharmacy_id,created_at:now(),updated_at:now(),product_id:it.product_id,batch_id:b.id,type:'adjustment',quantity:-it.quantity,before_qty:b.quantity,after_qty:b.quantity-it.quantity,reference_id:purchase_id,user_id,notes:reason}); }} await db.purchases.update(purchase_id,{status:'CANCELLED',updated_at:now()}); if(purchase.supplier_id&&purchase.remaining>0){const sp=await db.suppliers.get(purchase.supplier_id); if(sp) await db.suppliers.update(sp.id,{balance:Math.max(0,sp.balance-purchase.remaining),updated_at:now()});} await audit(user_id,'إلغاء فاتورة شراء','purchases',purchase_id,reason); }); }
