import type {LicenseCache,LicenseStatus} from '../types/models';
const KEY='alshifaa_license_cache', DEVICE='alshifaa_device_fingerprint';
export async function getDeviceId(){ let id=localStorage.getItem(DEVICE)||''; const extra=[navigator.userAgent,screen.width,screen.height,navigator.language].join('|'); if(!id){const raw=crypto.randomUUID()+extra; const h=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(raw)); id=Array.from(new Uint8Array(h)).map(b=>b.toString(16).padStart(2,'0')).join(''); localStorage.setItem(DEVICE,id); try{await indexedDB.open('alshifaa_device_anchor',1)}catch{}} return id; }
export function getCachedLicense():LicenseCache|null{
  const raw=localStorage.getItem(KEY);
  if(!raw) return null;
  try {
    const parsed=JSON.parse(raw) as Partial<LicenseCache>;
    if(!parsed || typeof parsed !== 'object') return null;
    return parsed as LicenseCache;
  } catch {
    localStorage.removeItem(KEY);
    return null;
  }
}
export function licenseGate(){
  const l=getCachedLicense();
  if(!l) return {ok:false,readOnly:true,message:'يرجى تفعيل الترخيص عبر الإنترنت أولاً'};
  const now=Date.now(), exp=l.license_type==='LIFETIME'||l.expires_at===null?Infinity:Date.parse(l.expires_at), last=Date.parse(l.last_validation);
  const graceDays=Number(l.grace_days);
  if(!l.signature || !l.status || !Number.isFinite(last) || !Number.isFinite(graceDays) || graceDays<0 || (l.license_type!=='LIFETIME'&&!Number.isFinite(exp))) return {ok:false,readOnly:true,message:'بيانات الترخيص المحلي غير صالحة، يرجى التحقق من الترخيص مجدداً'};
  if(['SUSPENDED','REVOKED'].includes(l.status)) return {ok:false,readOnly:true,message:'الترخيص موقوف أو ملغي'};
  if(l.license_type!=='LIFETIME'&&(l.status==='EXPIRED'||exp<now)) return {ok:false,readOnly:true,message:'انتهت صلاحية الترخيص'};
  if(now-last>graceDays*86400000) return {ok:false,readOnly:true,message:'انتهت مهلة العمل دون اتصال، يلزم التحقق عبر الإنترنت'};
  return {ok:true,readOnly:false,message:navigator.onLine?'● متصل':'● غير متصل - يمكنك متابعة العمل'};
}
export async function validateLicense(endpoint:string, license_key:string){
  const normalized=String(endpoint||'').trim().replace(/\/+$/,'');
  const key=String(license_key||'').trim();
  if(!/^https?:\/\//i.test(normalized)) throw new Error('رابط خادم التراخيص غير صالح');
  if(!key) throw new Error('أدخل مفتاح الترخيص');
  const device_id=await getDeviceId();
  let res:Response;
  try {
    res=await fetch(`${normalized}/functions/v1/license-check`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({license_key:key,device_id,product_code:'ALSHIFAA_ERP'})});
  } catch {
    throw new Error('تعذر الاتصال بخادم التراخيص');
  }
  let data:any;
  try { data=await res.json(); } catch { throw new Error('استجابة خادم التراخيص غير صالحة'); }
  if(!res.ok) throw new Error(data?.error||'تعذر التحقق من الترخيص');
  if(!data.signature || !data.status || (data.expires_at===undefined&&data.license_type!=='LIFETIME')) throw new Error('استجابة ترخيص غير صالحة');
  const license_type=String(data.license_type|| (data.expires_at===null?'LIFETIME':'ANNUAL')).toUpperCase();
  const cache:LicenseCache={...data,license_key:key,device_id,license_type,last_validation:new Date().toISOString(),last_seen:new Date().toISOString(),grace_days:Number(data.grace_days??7),status:data.status as LicenseStatus};
  if(!['ANNUAL','LIFETIME'].includes(license_type)||!Number.isFinite(cache.grace_days)||cache.grace_days<0||(license_type==='ANNUAL'&&(!cache.expires_at||!Number.isFinite(Date.parse(cache.expires_at))))) throw new Error('بيانات انتهاء الترخيص غير صالحة');
  localStorage.setItem(KEY,JSON.stringify(cache));
  return cache;
}
export function clearLicense(){localStorage.removeItem(KEY)}
