import {useLiveQuery} from 'dexie-react-hooks'; import {useState} from 'react'; import {db} from '../services/db'; import {cancelPurchase, postPurchase} from '../services/purchases'; import type {User} from '../types/models'; import {money} from '../utils/ids';
const labels:any={invoice_no:'رقم فاتورة الشراء',batch_number:'رقم التشغيلة',quantity:'الكمية',purchase_price:'سعر الشراء',selling_price:'سعر البيع',expiry_date:'تاريخ الصلاحية',paid:'المبلغ المدفوع'};
export default function Purchases({user}:{user:User}){const products=useLiveQuery(()=>db.products.toArray(),[])||[]; const purchases=useLiveQuery(async()=>{const rows=await db.purchases.toArray(); return rows.sort((a,b)=>String(b.created_at||b.date).localeCompare(String(a.created_at||a.date)));},[])||[]; const [f,setF]=useState<any>({invoice_no:'',paid:0,quantity:1}); const [msg,setMsg]=useState(''); async function save(e:any){e.preventDefault(); setMsg(''); try{await postPurchase(user.id,undefined,f.invoice_no||`P-${Date.now()}`,+f.paid,[{product_id:f.product_id,batch_number:f.batch_number,quantity:+f.quantity,purchase_price:+f.purchase_price,selling_price:+f.selling_price,expiry_date:f.expiry_date,discount:+(f.discount||0),tax:+(f.tax||0)}]); setF({paid:0,quantity:1}); setMsg('تم ترحيل فاتورة الشراء وتحديث المخزون.')}catch(e:any){setMsg(e.message)}} async function cancel(id:string){const reason=prompt('اكتب سبب إلغاء فاتورة الشراء'); if(!reason)return; try{await cancelPurchase(user.id,id,reason);setMsg('تم إلغاء فاتورة الشراء.')}catch(e:any){setMsg(e.message)}} return <section><h1>المشتريات</h1>{msg&&<div className="alert">{msg}</div>}<form className="card formgrid" onSubmit={save}><select required value={f.product_id||''} onChange={e=>setF({...f,product_id:e.target.value})}><option value="">اختر الدواء</option>{products.map(p=><option key={p.id} value={p.id}>{p.arabic_name}</option>)}</select>{['invoice_no','batch_number','quantity','purchase_price','selling_price','expiry_date','paid'].map(k=><input key={k} required={['batch_number','quantity','purchase_price','selling_price'].includes(k)} type={k.includes('date')?'date':k.includes('price')||k==='quantity'||k==='paid'?'number':'text'} value={f[k]||''} onChange={e=>setF({...f,[k]:e.target.value})} placeholder={labels[k]||k}/>) }<button>ترحيل الشراء</button></form><div className="card"><table><thead><tr><th>الفاتورة</th><th>التاريخ</th><th>الإجمالي</th><th>المتبقي</th><th>الحالة</th><th>إجراءات</th></tr></thead><tbody>{purchases.map(p=><tr key={p.id}><td>{p.invoice_no}</td><td>{p.date}</td><td>{money(p.total)}</td><td>{money(p.remaining)}</td><td><span className={`status ${p.status==='POSTED'?'ok':'bad'}`}>{p.status==='POSTED'?'مرحلة':'ملغاة'}</span></td><td>{p.status==='POSTED'&&<button className="danger" onClick={()=>cancel(p.id)}>إلغاء</button>}</td></tr>)}</tbody></table>{!purchases.length&&<p className="empty">لا توجد مشتريات بعد.</p>}</div></section>}
