import { db, getPharmacyId } from './db'; import type {Batch,Product,StockMovement} from '../types/models'; import { now, uid } from '../utils/ids'; import { audit } from './audit';
export async function productSearch(q:string){ const s=q.trim().toLowerCase(); const all=await db.products.toArray(); return all.filter(p=>p.active && (!s || [p.arabic_name,p.english_name,p.generic_name,p.barcode,p.alternative_barcode,p.sku,p.manufacturer].some(v=>String(v||'').toLowerCase().includes(s)))).slice(0,50); }
export async function availableBatches(product_id:string){ const rows=await db.batches.where('product_id').equals(product_id).toArray(); const today=new Date().toISOString().slice(0,10); return rows.filter(b=>b.quantity>0 && (!b.expiry_date || b.expiry_date>=today)).sort((a,b)=>(a.expiry_date||'9999').localeCompare(b.expiry_date||'9999')); }
export async function adjustStock(user_id:string, product_id:string, batch_id:string|undefined, qtyDelta:number, type:StockMovement['type'], notes?:string){ const pharmacy_id=getPharmacyId(); if(!product_id||!Number.isFinite(qtyDelta)||qtyDelta===0) throw new Error('بيانات تسوية المخزون غير صالحة'); await db.transaction('rw',db.batches,db.stock_movements,db.audit_logs,async()=>{ let before=0, after=0; if(batch_id){ const b=await db.batches.get(batch_id); if(!b) throw new Error('لم يتم العثور على التشغيلة'); before=b.quantity; after=before+qtyDelta; if(after<0) throw new Error('الكمية غير كافية'); await db.batches.update(batch_id,{quantity:after,updated_at:now()}); } else { throw new Error('اختر تشغيلة قبل إجراء التسوية'); } const mv:StockMovement={id:uid('move'),pharmacy_id,created_at:now(),updated_at:now(),product_id,batch_id,type,quantity:qtyDelta,before_qty:before,after_qty:after,user_id,notes}; await db.stock_movements.add(mv); await audit(user_id,'stock_adjustment','stock_movements',mv.id,mv); }); }
export async function lowStock(){ const products=await db.products.toArray(); const batches=await db.batches.toArray(); return products.filter(p=>batches.filter(b=>b.product_id===p.id).reduce((s,b)=>s+b.quantity,0)<=p.reorder_level); }
export async function expiryBuckets(){ const batches=await db.batches.toArray(); const today=new Date(); const diff=(d?:string)=>d?Math.ceil((new Date(d).getTime()-today.getTime())/86400000):99999; return {expired:batches.filter(b=>diff(b.expiry_date)<0),d7:batches.filter(b=>diff(b.expiry_date)>=0&&diff(b.expiry_date)<=7),d30:batches.filter(b=>diff(b.expiry_date)>7&&diff(b.expiry_date)<=30),d60:batches.filter(b=>diff(b.expiry_date)>30&&diff(b.expiry_date)<=60),d90:batches.filter(b=>diff(b.expiry_date)>60&&diff(b.expiry_date)<=90)}; }
export async function saveProduct(user_id:string,p:Partial<Product>){ const pharmacy_id=getPharmacyId(); const name=String(p.arabic_name||'').trim(); const base={pharmacy_id,updated_at:now(),active:true,tax:0,reorder_level:0,purchase_price:0,selling_price:0,...p,arabic_name:name} as Product; if(!base.arabic_name) throw new Error('اسم الدواء مطلوب'); if(!Number.isFinite(base.selling_price)||base.selling_price<0||!Number.isFinite(base.purchase_price)||base.purchase_price<0) throw new Error('الأسعار غير صالحة'); if(!base.id){base.id=uid('prod'); base.created_at=now(); await db.products.add(base); await audit(user_id,'product_creation','products',base.id,base);} else {await db.products.update(base.id,{...base,updated_at:now()}); await audit(user_id,'product_modification','products',base.id,base);} return base; }
export async function saveBatch(user_id:string,b:Partial<Batch>){ const pharmacy_id=getPharmacyId(); const row={pharmacy_id,updated_at:now(),quantity:0,initial_quantity:0,purchase_price:0,selling_price:0,...b} as Batch; if(!row.product_id||!row.batch_number?.trim()) throw new Error('اختر الدواء وأدخل رقم التشغيلة'); if(!Number.isFinite(row.quantity)||row.quantity<0) throw new Error('الكمية غير صالحة'); if(!row.id){row.id=uid('batch'); row.created_at=now(); row.initial_quantity=row.quantity; await db.batches.add(row)} else await db.batches.update(row.id,row); await audit(user_id,'batch_save','batches',row.id,row); return row; }
