import {useState} from 'react'; import {getCachedLicense,licenseGate,validateLicense,clearLicense} from '../services/license';
export default function License(){const [endpoint,setEndpoint]=useState(localStorage.getItem('alshifaa_license_endpoint')||''),[key,setKey]=useState(''),[msg,setMsg]=useState(''); const l=getCachedLicense(), gate=licenseGate(); async function val(){try{localStorage.setItem('alshifaa_license_endpoint',endpoint); const r=await validateLicense(endpoint,key); setMsg(`تم التحقق بنجاح: ${r.status}`)}catch(e:any){setMsg(e.message)}} return <section><h1>الترخيص</h1><div className="card"><p>{gate.message}</p><input value={endpoint} onChange={e=>setEndpoint(e.target.value)} placeholder="رابط مشروع التراخيص"/><input value={key} onChange={e=>setKey(e.target.value)} placeholder="مفتاح الترخيص"/><button onClick={val}>تحقق وتفعيل</button><button className="ghost" onClick={()=>{clearLicense();location.reload()}}>مسح الترخيص المحلي</button>{msg&&<div className="alert">{msg}</div>}{l&&<div className="license-summary"><p><b>حالة الترخيص:</b> {l.status}</p><p><b>نوع الترخيص:</b> {l.license_type==='LIFETIME'?'مدى الحياة':'سنوي'}</p><p><b>اسم الصيدلية:</b> {l.pharmacy_name}</p><p><b>تاريخ الانتهاء:</b> {l.license_type==='LIFETIME'?'لا ينتهي':l.expires_at?.slice(0,10)}</p></div>}</div></section>}
