import {useState} from 'react'; import {login} from '../services/auth'; import type {User} from '../types/models';
export default function Login({onLogin}:{onLogin:(u:User)=>void}){const [username,setU]=useState(''),[password,setP]=useState(''),[err,setErr]=useState(''); async function submit(e:any){e.preventDefault(); setErr(''); try{onLogin(await login(username,password))}catch(x:any){setErr(x.message)}} return <div className="login"><form onSubmit={submit} className="card"><div className="login-brand"><img src="brand-logo.png" alt="شعار النجاح لإدارة الصيدليات"/><h1>النجاح لإدارة الصيدليات</h1><p>نظام إدارة الصيدليات ونقاط البيع والمخزون</p></div><input value={username} onChange={e=>setU(e.target.value)} placeholder="اسم المستخدم أو البريد" autoComplete="username"/><input type="password" value={password} onChange={e=>setP(e.target.value)} placeholder="كلمة المرور" autoComplete="current-password"/><button>تسجيل الدخول</button>{err&&<div className="alert">{err}</div>}<div className="login-support">الدعم والمبيعات: <a href="tel:0121164581">0121164581</a> — واتساب: <a href="https://wa.me/249969696787">0969696787</a></div></form></div>}
