import { db } from './db'; import { today } from '../utils/ids';
const tables=['products','batches','sales','sale_items','purchases','purchase_items','customers','suppliers','payments','expenses','returns','stock_movements','settings','users','audit_logs'] as const;
export async function exportBackup(){ const payload:any={version:1,created_at:new Date().toISOString(),tables:{}}; for(const t of tables) payload.tables[t]=await (db as any)[t].toArray(); return new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}); }
export async function downloadBackup(){ const blob=await exportBackup(); const a=document.createElement('a'); const url=URL.createObjectURL(blob); a.href=url; a.download=`ALSHIFAA_BACKUP_${today()}.json`; a.click(); setTimeout(()=>URL.revokeObjectURL(url),1000); }
export async function restoreBackup(file:File){ const safety=await exportBackup(); const text=await file.text(); let data; try{data=JSON.parse(text)}catch{throw new Error('ملف النسخة الاحتياطية تالف')} if(!data||data.version!==1||!data.tables||typeof data.tables!=='object') throw new Error('ملف النسخة الاحتياطية غير صالح أو غير مدعوم'); for(const t of tables){if(data.tables[t]!==undefined&&!Array.isArray(data.tables[t])) throw new Error(`بيانات جدول ${t} غير صالحة`);} await (db.transaction as any)('rw',tables.map(t=>(db as any)[t]),async()=>{ for(const t of tables){ await (db as any)[t].clear(); if(Array.isArray(data.tables[t])) await (db as any)[t].bulkPut(data.tables[t]); }}); return safety; }
export async function exportCsv(table:string){ const rows=await (db as any)[table].toArray(); if(!rows.length) return new Blob([''],{type:'text/csv'}); const cols=Object.keys(rows[0]); const esc=(v:any)=>`"${String(v??'').replace(/"/g,'""')}"`; return new Blob([cols.join(',')+'\n'+rows.map((r:any)=>cols.map(c=>esc(r[c])).join(',')).join('\n')],{type:'text/csv'}); }
