import { db, getPharmacyId } from './db';
import type { Return as ReturnRow } from '../types/models';
import { now, uid } from '../utils/ids';
import { audit } from './audit';

/**
 * Registers a complete return for a completed sale.
 * Complete returns are deliberately used here so totals, stock and customer
 * balances cannot drift apart through a partially implemented refund flow.
 */
export async function returnSale(user_id: string, sale_id: string, reason: string) {
  const sale = await db.sales.get(sale_id);
  if (!sale || sale.status !== 'COMPLETED') {
    throw new Error('الفاتورة غير قابلة للترجيع');
  }

  const items = await db.sale_items.where('sale_id').equals(sale_id).toArray();
  if (!items.length) throw new Error('لا توجد أصناف في الفاتورة');

  const pharmacy_id = getPharmacyId();
  const returnedAt = now();

  await db.transaction(
    'rw',
    [
      db.sales,
      db.sale_items,
      db.batches,
      db.returns,
      db.stock_movements,
      db.customers,
      db.audit_logs,
    ],
    async () => {
      const alreadyReturned = await db.returns
        .where('source_id')
        .equals(sale_id)
        .count();
      if (alreadyReturned > 0) throw new Error('تم ترجيع هذه الفاتورة مسبقاً');

      const returnRows: ReturnRow[] = [];
      for (const item of items) {
        const batch = await db.batches.get(item.batch_id);
        if (!batch) throw new Error('لم يتم العثور على تشغيلة أحد الأصناف');

        const before = batch.quantity;
        const after = before + item.quantity;
        await db.batches.update(batch.id, {
          quantity: after,
          updated_at: returnedAt,
        });

        returnRows.push({
          id: uid('return'),
          pharmacy_id,
          created_at: returnedAt,
          updated_at: returnedAt,
          type: 'SALE_RETURN',
          source_id: sale_id,
          product_id: item.product_id,
          quantity: item.quantity,
          reason: reason.trim(),
        });

        await db.stock_movements.add({
          id: uid('move'),
          pharmacy_id,
          created_at: returnedAt,
          updated_at: returnedAt,
          product_id: item.product_id,
          batch_id: item.batch_id,
          type: 'return',
          quantity: item.quantity,
          before_qty: before,
          after_qty: after,
          reference_id: sale_id,
          user_id,
          notes: reason.trim(),
        });
      }

      await db.returns.bulkAdd(returnRows);
      await db.sales.update(sale_id, {
        status: 'RETURNED',
        updated_at: returnedAt,
      });

      if (sale.customer_id && sale.remaining > 0) {
        const customer = await db.customers.get(sale.customer_id);
        if (customer) {
          await db.customers.update(customer.id, {
            balance: Math.max(0, customer.balance - sale.remaining),
            updated_at: returnedAt,
          });
        }
      }

      await audit(user_id, 'sale_return', 'returns', sale_id, {
        reason,
        sale_id,
        item_count: items.length,
      });
    },
  );
}