import { db } from './db';
export async function dashboardStats(){ const today=new Date().toISOString().slice(0,10); const [sales,purchases,expenses,customers,suppliers,batches]=await Promise.all([db.sales.toArray(),db.purchases.toArray(),db.expenses.toArray(),db.customers.toArray(),db.suppliers.toArray(),db.batches.toArray()]); const todaysSales=sales.filter(s=>s.created_at.slice(0,10)===today&&s.status==='COMPLETED'); const todaysPurchases=purchases.filter(p=>p.date===today&&p.status==='POSTED'); const todaysExpenses=expenses.filter(e=>e.date===today); return {todaySales:todaysSales.reduce((a,s)=>a+s.total,0),todayPurchases:todaysPurchases.reduce((a,p)=>a+p.total,0),todayProfit:todaysSales.reduce((a,s)=>a+s.profit,0)-todaysExpenses.reduce((a,e)=>a+e.amount,0),cashSales:todaysSales.filter(s=>s.payment_method==='Cash').reduce((a,s)=>a+s.total,0),creditSales:todaysSales.filter(s=>s.remaining>0).reduce((a,s)=>a+s.remaining,0),expenses:todaysExpenses.reduce((a,e)=>a+e.amount,0),stockValue:batches.reduce((a,b)=>a+b.quantity*b.purchase_price,0),customerDebts:customers.reduce((a,c)=>a+c.balance,0),supplierDebts:suppliers.reduce((a,s)=>a+s.balance,0)}; }
export async function series(days=30){ const safeDays=Math.max(1,Math.floor(days)); const start=new Date(); start.setDate(start.getDate()-safeDays+1); const key=(d:Date)=>d.toISOString().slice(0,10); const map:any={}; for(let i=0;i<safeDays;i++){const d=new Date(start); d.setDate(start.getDate()+i); map[key(d)]={date:key(d),sales:0,purchases:0,expenses:0,profit:0};} for(const s of await db.sales.toArray()){if(s.status!=='COMPLETED') continue; const k=s.created_at.slice(0,10); if(map[k]){map[k].sales+=s.total; map[k].profit+=s.profit}} for(const p of await db.purchases.toArray()){if(p.status!=='POSTED') continue; if(map[p.date]) map[p.date].purchases+=p.total} for(const e of await db.expenses.toArray()){if(map[e.date]){map[e.date].expenses+=e.amount; map[e.date].profit-=e.amount}} return Object.values(map); }
